<template>
 <section class="house-tournament" data-house-tournament>
  <header><div><small>MAISON DES COMBATS · ÉLIMINATION DIRECTE</small><h3>{{ state.phase==='finished'?'Le tournoi a son vainqueur':state.phase==='cancelled'?'Tournoi interrompu':'Tournoi 1v1' }}</h3></div><span class="tournament-count">{{state.participants.length}}<small>/ 16</small></span></header>
  <p class="tournament-intro" v-if="state.phase==='waiting'">Rejoignez un socle bleu ou rouge. Les couleurs ne séparent pas les participants : tous entrent dans le même tirage.</p>
  <p class="tournament-intro" v-else-if="state.phase==='running'">Un duel à la fois. Les dresseurs en attente et les éliminés regardent automatiquement le combat. La préparation s’ouvre quand vient ton tour.</p>
  <div class="tournament-rules"><span>{{state.config.level?'Niveau '+state.config.level:'Niveaux libres'}}</span><span v-if="state.config.legendaryLimit!==false">1 légendaire / fabuleux par équipe</span><span v-if="state.config.uniqueItems">Objets uniques</span><span>{{state.config.money?money(state.config.money)+' ₽ par joueur et par duel':'Sans mise d’argent'}}</span><span v-if="state.config.pokemonStake">Pokémon misés avant chaque duel</span><span>Sans XP</span></div>
  <div v-if="state.phase==='waiting'" class="tournament-registration"><div v-for="p in state.participants" :key="p.userId" :class="{self:p.userId===userId}"><span>{{p.userId===state.hostId?'✦':'◇'}}</span><b>{{p.username}}</b><small>{{p.userId===userId?'Toi':p.userId===state.hostId?'Organisateur':'Inscrit'}}</small></div><p v-if="!state.participants.length">Les socles sont libres.</p></div>
  <div v-if="state.rounds.length" class="tournament-bracket" aria-label="Tableau des affrontements">
   <section v-for="(round,i) in state.rounds" :key="round.index" class="tournament-round"><h4>{{roundLabel(round,i)}}<small>Tour {{i+1}}</small></h4><article v-for="m in round.matches" :key="m.id" :class="['match-'+m.phase,{current:m.id===state.currentMatchId}]" :data-tournament-match="m.id"><div v-for="(id,side) in m.players" :key="side" :class="{winner:m.winnerId===id&&!!id,self:id===userId,eliminated:m.phase==='finished'&&id&&m.winnerId!==id}"><span>{{m.winnerId===id&&id?'✓':side+1}}</span><b>{{id?name(id):'Qualification automatique'}}</b></div><small>{{matchLabel(m)}}</small><small v-if="m.tiebreak">Départagé après égalité</small></article></section>
   <section v-if="state.phase==='finished'" class="tournament-podium"><span>✧</span><small>VAINQUEUR</small><h4>{{name(state.winnerId)}}</h4><p>Dernier dresseur debout.</p></section>
  </div>
  <div v-if="state.phase==='finished'" class="tournament-congratulations" role="status">{{state.winnerId===userId?'Tu remportes le tournoi !':'Victoire de '+name(state.winnerId)+' !'}} Les résultats et mises de chaque duel sont sauvegardés.</div>
  <p v-if="state.error" class="tournament-error" role="alert">{{state.error}}</p>
  <details class="tournament-guide"><summary>Règles et déroulement</summary><p>De 3 à 16 participants. Tirage aléatoire des adversaires et des qualifications automatiques. Aucun paiement pour une qualification automatique.</p><p>Chaque duel reprend vos réglages et soigne une copie de l’équipe. L’équipe d’Aventure reste intacte. Les mises sont vérifiées, puis confirmées par les deux adversaires avant chaque combat.</p><p>Les déconnexions pendant un combat disposent de 30 secondes de grâce. Un abandon est un forfait. En cas d’égalité, les mises sont rendues et la qualification départagée par les Pokémon aptes, puis les PV restants, puis un tirage si nécessaire.</p></details>
  <div v-if="confirmLeave" class="tournament-leave-confirm" role="alert"><p>{{state.phase==='waiting'?(userId===state.hostId?'Annuler l’inscription de tout le tournoi ?':'Te retirer de la liste des participants ?'):'Quitter le tournoi ? Ton duel actuel, ou le prochain, sera un forfait. Une mise déjà engagée suit les règles du duel.'}}</p><button :disabled="busy" @click="command('tournamentLeave')">Confirmer</button><button :disabled="busy" @click="confirmLeave=false">Rester</button></div>
  <footer v-else><span v-if="state.phase==='waiting'">{{state.participants.length<3?'Au moins 3 dresseurs sur les socles.':'Les participants sont prêts pour le tirage.'}}</span><button v-if="state.phase==='waiting'&&userId===state.hostId" class="tournament-primary" :disabled="busy||state.participants.length<3" @click="command('tournamentStart')">Lancer le tournoi</button><button v-if="['waiting','running'].includes(state.phase)&&canLeave" :disabled="busy" @click="confirmLeave=true">{{state.phase==='waiting'?'Annuler':'Quitter le tournoi'}}</button><button v-if="['finished','cancelled'].includes(state.phase)||(state.you<0||state.participants[state.you]?.left)&&state.hostId!==userId" @click="$emit('configure')">{{['finished','cancelled'].includes(state.phase)?'Organiser un autre combat':'Autres modes'}}</button></footer>
 </section>
</template>
<script>
export default{name:'HouseTournamentPanel',props:{state:Object,userId:Number,busy:Boolean},data:()=>({confirmLeave:false}),computed:{canLeave(){return this.userId===this.state.hostId||this.state.you>=0&&!this.state.participants[this.state.you]?.left;}},methods:{money:n=>Number(n).toLocaleString('fr-FR'),name(id){return this.state.participants.find(p=>p.userId===id)?.username||'—';},roundLabel(round){return round.matches.length===1?'Finale':round.matches.length===2?'Demi-finales':round.matches.length===4?'Quarts de finale':round.matches.length===8?'Huitièmes':'Qualification';},matchLabel(m){return{waiting:'À venir',preparation:'Préparation des équipes',battle:'En combat',finished:m.reason==='forfeit'?'Qualification par forfait':'Terminé',bye:'Qualifié sans duel'}[m.phase]||m.phase;},command(name){this.confirmLeave=false;this.$emit('command',name,{id:this.state.id});}}};
</script>
