dding:9px;position:relative}.tournament-round article.current{border-color:var(--journal-accent);box-shadow:inset 3px 0 var(--journal-accent)}.tournament-round article>div{display:flex;gap:8px;align-items:center;padding:8px 5px;border-radius:5px;font-size:12px}.tournament-round article>div+div{border-top:1px solid var(--journal-border)}.tournament-round article>div>span{width:17px;color:var(--journal-muted);font-size:10px}.tournament-round b{overflow-wrap:anywhere}.tournament-round .winner{color:var(--journal-accent);background:var(--journal-selected)}.tournament-round .self b{text-decoration:underline;text-underline-offset:4px}.tournament-round .eliminated{opacity:.5}.tournament-round article>small{display:block;font-size:9px;color:var(--journal-muted);padding:8px 5px 2px}.tournament-round article:after{content:'';position:absolute;right:-19px;top:50%;width:18px;border-top:1px solid var(--journal-border)}.tournament-podium{flex:0 0 200px;display:flex;flex-direction:column;justify-content:center;text-align:center;color:var(--journal-accent);padding:20px}.tournament-podium>span{font-size:58px;color:#bd9c5d}.tournament-podium>small{font-size:9px;letter-spacing:.14em}.tournament-podium h4{font-size:20px;overflow-wrap:anywhere}.tournament-podium p{font-size:11px;color:var(--journal-muted)}.tournament-congratulations{padding:14px;border:1px solid #bda56b;border-radius:9px;background:#baa46313;line-height:1.6;margin:12px 0}.tournament-error{color:var(--journal-danger);line-height:1.6}.tournament-guide{font-size:11px;color:var(--journal-muted);margin:18px 0}.tournament-guide summary{cursor:pointer;min-height:36px;display:list-item;padding:8px 0}.tournament-guide p{line-height:1.7}.house-tournament footer{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;border-top:1px solid var(--journal-border);padding-top:14px}.house-tournament footer>span{margin-right:auto;align-self:center;font-size:11px;color:var(--journal-muted)}.house-tournament button{min-height:42px;bor